use kimo_core::{color::finish,effects::{Frame,Params},keyframe::Prop};
fn p(vals:&[(&str,f64)])->Params{let mut p=Params::new();for(k,v)in vals{p.insert((*k).into(),Prop::new(*v));}p}
fn off()->Params{p(&[("bloom",0.),("halation",0.),("grain",0.),("vignette",0.)])}
fn flat(w:usize,h:usize,c:[f32;4])->Frame{Frame{w,h,d:c.repeat(w*h)}}
#[test]fn exact_identity_extended(){let mut f=flat(32,17,[-0.3,2.5,0.7,0.4]);let a=f.d.clone();finish::apply(&off(),&mut f,0.,10).unwrap();assert_eq!(a,f.d);}
#[test]fn seed_determinism_variation_luma_alpha(){let mut a=flat(128,128,[0.5,0.5,0.5,0.4]);let mut b=flat(128,128,[0.5,0.5,0.5,0.4]);let mut c=flat(128,128,[0.5,0.5,0.5,0.4]);let mut q=off();q.insert("grain".into(),Prop::new(0.1));finish::apply(&q,&mut a,0.,25).unwrap();finish::apply(&q,&mut b,7.,25).unwrap();finish::apply(&q,&mut c,0.,26).unwrap();assert_eq!(a.d,b.d);assert_ne!(a.d,c.d);let mean=a.d.chunks_exact(4).map(|v|{assert_eq!(v[0],v[1]);assert_eq!(v[1],v[2]);assert_eq!(v[3],0.4);v[0]-0.5}).sum::<f32>()/16384.;assert!(mean.abs()<0.001);}
#[test]fn impulse_red_rim_and_transparent_no_emission(){let mut f=flat(65,65,[0.,0.,0.,1.]);let i=(32*65+32)*4;f.d[i..i+3].fill(1.);let mut q=off();q.insert("halation".into(),Prop::new(0.5));q.insert("radius".into(),Prop::new(0.1));finish::apply(&q,&mut f,0.,0).unwrap();let a=(32*65+35)*4;assert!(f.d[a]>f.d[a+1]&&f.d[a+1]>f.d[a+2]&&f.d[a+2]>0.);assert!((f.d[i]-1.).abs()<1e-6);let mut f=flat(65,65,[0.,0.,0.,1.]);f.d[i..i+3].fill(100.);f.d[i+3]=0.;let orig=f.d.clone();finish::apply(&q,&mut f,0.,0).unwrap();assert_eq!(f.d,orig);}
#[test]fn grain_last_no_scatter_feedback(){let mut a=flat(40,40,[0.72,0.6,0.4,1.]);let mut b=flat(40,40,[0.72,0.6,0.4,1.]);let mut c=flat(40,40,[0.72,0.6,0.4,1.]);let orig=c.d.clone();let mut q=Params::new();q.insert("grain".into(),Prop::new(0.));finish::apply(&q,&mut a,0.,18).unwrap();q.insert("grain".into(),Prop::new(0.1));finish::apply(&q,&mut b,0.,18).unwrap();let mut q=off();q.insert("grain".into(),Prop::new(0.1));finish::apply(&q,&mut c,0.,18).unwrap();for i in 0..a.d.len(){if i%4!=3{assert!(((b.d[i]-a.d[i])-(c.d[i]-orig[i])).abs()<2e-7);}}}
#[test]fn invalid_atomic(){for(k,v)in[("grain",f64::NAN),("radius",-1.),("knee",0.),("grain_size",100.)]{let mut f=flat(5,5,[0.4,0.3,0.2,1.]);let orig=f.d.clone();assert!(finish::apply(&p(&[(k,v)]),&mut f,0.,0).is_err());assert_eq!(f.d,orig);}}
#[test]fn outer_timeline_bounded_equals_export(){use kimo_core::{commands::{Session,dispatch},render};use serde_json::json;let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":24,"fps":25})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[0.5,0.5,0.5],"start":2,"duration":2})).unwrap()["clip_id"].clone();dispatch(&mut s,"add_effect",&json!({"clip_id":c,"kind":"film_finish","params":{"bloom":0,"halation":0,"vignette":0,"grain":0.1}})).unwrap();let cold=render::render_frame(&s.project,2.4,&s.cache).unwrap();let mut match_frame=None;for i in 0..100{let f=render::render_frame(&s.project,i as f64/25.,&s.cache).unwrap();if i==60{match_frame=Some(f);}}assert_eq!(cold.d,match_frame.unwrap().d);let mut direct=flat(32,24,[0.5,0.5,0.5,1.]);let mut q=off();q.insert("grain".into(),Prop::new(0.1));finish::apply(&q,&mut direct,0.4,60).unwrap();assert_eq!(cold.d,direct.d);}
#[test]fn tiny_and_nonfinite_frames(){for(w,h)in[(0,0),(1,1),(1,4),(4,1)]{let mut f=flat(w,h,[0.9,0.8,0.7,0.5]);finish::apply(&Params::new(),&mut f,0.,1).unwrap();assert!(f.d.iter().all(|v|v.is_finite()));for v in f.d.chunks_exact(4){assert_eq!(v[3],0.5);}}for mut f in [Frame{w:1,h:1,d:vec![]},flat(1,1,[f32::NAN,0.,0.,1.]),flat(1,1,[1.,1.,1.,2.])]{assert!(finish::apply(&Params::new(),&mut f,0.,0).is_err());}}
#[test]fn wrapper_matches_explicit_chain(){use kimo_core::{effects::apply,color::{wrapper,managed},model::Effect};let mut e=Effect{id:"e".into(),kind:"film_finish".into(),params:Params::new(),strings:Default::default()};wrapper::configure(&mut e,3,0,1).unwrap();let mut f=flat(9,7,[0.9,0.2,0.1,0.7]);let mut r=Frame{w:f.w,h:f.h,d:f.d.clone()};let mut q=p(&[("from_gamut",3.),("to_gamut",0.),("from_transfer",0.),("to_transfer",1.)]);managed::apply(&q,&mut r,0.).unwrap();finish::apply(&e.params,&mut r,0.,125).unwrap();q=p(&[("from_gamut",0.),("to_gamut",3.),("from_transfer",1.),("to_transfer",0.)]);managed::apply(&q,&mut r,0.).unwrap();apply(&e.kind,&e.params,&e.strings,&mut f,0.,125).unwrap();assert_eq!(f.d,r.d);}
